20	import IndicatorAxis from './IndicatorAxis';
21	import IntervalScale from '../../scale/Interval';
22	import * as numberUtil from '../../util/number';
23	import { CoordinateSystemMaster, CoordinateSystem } from '../CoordinateSystem';
