33	
34	class Radar implements CoordinateSystem, CoordinateSystemMaster {
35	
36	    readonly type: 'radar';
37	    /**
38	     *
39	     * Radar dimensions
40	     */
41	    readonly dimensions: string[] = [];
42	
43	    cx: number;
44	
45	    cy: number;
46	
47	    r: number;
48	
49	    r0: number;
50	
51	    startAngle: number;
52	
53	    private _model: RadarModel;
54	
55	    private _indicatorAxes: IndicatorAxis[];
56	
57	    constructor(radarModel: RadarModel, ecModel: GlobalModel, api: ExtensionAPI) {
58	        this._model = radarModel;
59	
60	        this._indicatorAxes = map(radarModel.getIndicatorModels(), function (indicatorModel, idx) {
61	            const dim = 'indicator_' + idx;
62	            const indicatorAxis = new IndicatorAxis(dim,
63	                new IntervalScale()
64	                // (indicatorModel.get('axisType') === 'log') ? new LogScale() : new IntervalScale()
65	            );
66	            indicatorAxis.name = indicatorModel.get('name');
67	            // Inject model and axis
68	            indicatorAxis.model = indicatorModel;
69	            indicatorModel.axis = indicatorAxis;
70	            this.dimensions.push(dim);
71	            return indicatorAxis;
72	        }, this);
73	
74	        this.resize(radarModel, api);
75	    }
76	
77	    getIndicatorAxes() {
78	        return this._indicatorAxes;
79	    }
80	
81	    dataToPoint(value: ScaleDataValue, indicatorIndex: number) {
82	        const indicatorAxis = this._indicatorAxes[indicatorIndex];
83	
84	        return this.coordToPoint(indicatorAxis.dataToCoord(value), indicatorIndex);
85	    }
86	
87	    // TODO: API should be coordToPoint([coord, indicatorIndex])
88	    coordToPoint(coord: number, indicatorIndex: number) {
89	        const indicatorAxis = this._indicatorAxes[indicatorIndex];
90	        const angle = indicatorAxis.angle;
91	        const x = this.cx + coord * Math.cos(angle);
92	        const y = this.cy - coord * Math.sin(angle);
93	        return [x, y];
94	    }
95	
96	    pointToData(pt: number[]) {
97	        let dx = pt[0] - this.cx;
98	        let dy = pt[1] - this.cy;
99	        const radius = Math.sqrt(dx * dx + dy * dy);
100	        dx /= radius;
101	        dy /= radius;
102	
103	        const radian = Math.atan2(-dy, dx);
104	
105	        // Find the closest angle
106	        // FIXME index can calculated directly
107	        let minRadianDiff = Infinity;
108	        let closestAxis;
109	        let closestAxisIdx = -1;
110	        for (let i = 0; i < this._indicatorAxes.length; i++) {
111	            const indicatorAxis = this._indicatorAxes[i];
112	            const diff = Math.abs(radian - indicatorAxis.angle);
113	            if (diff < minRadianDiff) {
114	                closestAxis = indicatorAxis;
115	                closestAxisIdx = i;
116	                minRadianDiff = diff;
117	            }
118	        }
119	
120	        return [closestAxisIdx, +(closestAxis && closestAxis.coordToData(radius))];
121	    }
122	
123	    resize(radarModel: RadarModel, api: ExtensionAPI) {
124	        const refContainer = createBoxLayoutReference(radarModel, api).refContainer;
125	
126	        const center = radarModel.get('center');
127	        const clockwise = radarModel.get('clockwise') || false;
128	        const viewSize = Math.min(refContainer.width, refContainer.height) / 2;
129	        this.cx = numberUtil.parsePercent(center[0], refContainer.width) + refContainer.x;
130	        this.cy = numberUtil.parsePercent(center[1], refContainer.height) + refContainer.y;
131	
132	        this.startAngle = radarModel.get('startAngle') * Math.PI / 180;
133	
134	        // radius may be single value like `20`, `'80%'`, or array like `[10, '80%']`
135	        let radius = radarModel.get('radius');
136	        if (isString(radius) || isNumber(radius)) {
137	            radius = [0, radius];
138	        }
139	        this.r0 = numberUtil.parsePercent(radius[0], viewSize);
140	        this.r = numberUtil.parsePercent(radius[1], viewSize);
141	
142	        const sign = clockwise ? -1 : 1;
143	
144	        each(this._indicatorAxes, function (indicatorAxis, idx) {
145	            indicatorAxis.setExtent(this.r0, this.r);
146	            let angle = (this.startAngle + sign * idx * Math.PI * 2 / this._indicatorAxes.length);
147	            // Normalize to [-PI, PI]
148	            angle = Math.atan2(Math.sin(angle), Math.cos(angle));
149	            indicatorAxis.angle = angle;
150	        }, this);
151	    }
152	
153	    update(ecModel: GlobalModel, api: ExtensionAPI) {
154	        const indicatorAxes = this._indicatorAxes;
155	        const radarModel = this._model;
156	        each(indicatorAxes, function (indicatorAxis) {
157	            indicatorAxis.scale.setExtent(Infinity, -Infinity);
158	        });
159	        ecModel.eachSeriesByType('radar', function (radarSeries, idx) {
160	            if (radarSeries.get('coordinateSystem') !== 'radar'
161	                // @ts-ignore
162	                || ecModel.getComponent('radar', radarSeries.get('radarIndex')) !== radarModel
163	            ) {
164	                return;
165	            }
166	            const data = radarSeries.getData();
167	            each(indicatorAxes, function (indicatorAxis) {
168	                indicatorAxis.scale.unionExtentFromData(data, data.mapDimension(indicatorAxis.dim));
169	            });
170	        }, this);
171	
172	        const splitNumber = radarModel.get('splitNumber');
173	        const dummyScale = new IntervalScale();
174	        dummyScale.setExtent(0, splitNumber);
175	        dummyScale.setInterval(1);
176	        // Force all the axis fixing the maxSplitNumber.
177	        each(indicatorAxes, function (indicatorAxis, idx) {
178	            alignScaleTicks(
179	                indicatorAxis.scale as IntervalScale,
180	                indicatorAxis.model,
181	                dummyScale
182	            );
183	        });
184	    }
185	
186	    convertToPixel(ecModel: GlobalModel, finder: ParsedModelFinder, value: ScaleDataValue[]): never {
187	        console.warn('Not implemented.');
188	        return null as never;
189	    }
190	    convertFromPixel(ecModel: GlobalModel, finder: ParsedModelFinder, pixel: number[]): never {
191	        console.warn('Not implemented.');
192	        return null as never;
193	    }
194	    containPoint(point: number[]): boolean {
195	        console.warn('Not implemented.');
196	        return false;
197	    }
198	    /**
199	     * Radar dimensions is based on the data
200	     */
201	    static dimensions: string[] = [];
202	
203	    static create(ecModel: GlobalModel, api: ExtensionAPI) {
204	        const radarList: Radar[] = [];
205	        ecModel.eachComponent('radar', function (radarModel: RadarModel) {
206	            const radar = new Radar(radarModel, ecModel, api);
207	            radarList.push(radar);
208	            radarModel.coordinateSystem = radar;
209	        });
210	        ecModel.eachSeriesByType('radar', function (radarSeries) {
211	            if (radarSeries.get('coordinateSystem') === 'radar') {
212	                // Inject coordinate system
213	                // @ts-ignore
214	                radarSeries.coordinateSystem = radarList[radarSeries.get('radarIndex') || 0];
215	            }
216	        });
217	        return radarList;
218	    }
219	}
220	
221	
222	export default Radar;

