// Regression test for `radar.clockwise` option.
import { createChart, removeChart } from '../../test/ut/core/utHelper';
import Radar from '../../src/coord/radar/Radar';

function getRadar(clockwise?: boolean) {
    const chart = createChart({ width: 500, height: 400 });
    chart.setOption({
        animation: false,
        radar: {
            clockwise: clockwise,
            startAngle: 90,
            indicator: [
                { name: 'a', max: 10 },
                { name: 'b', max: 10 },
                { name: 'c', max: 10 },
                { name: 'd', max: 10 }
            ]
        },
        series: [{ type: 'radar', data: [{ value: [1, 2, 3, 4] }] }]
    });
    const radar = (chart.getModel().getComponent('radar') as any).coordinateSystem as Radar;
    return { chart, radar };
}

describe('radar clockwise option', function () {
    it('default keeps the legacy counter-clockwise layout', function () {
        const { chart, radar } = getRadar();
        const angles = radar.getIndicatorAxes().map(axis => axis.angle);
        // 4 indicators, startAngle 90deg: PI/2, 0, -PI/2, -PI (normalized)
        expect(angles[0]).toBeCloseTo(Math.PI / 2);
        expect(angles[1]).toBeCloseTo(0);
        expect(angles[2]).toBeCloseTo(-Math.PI / 2);
        expect(angles[3]).toBeCloseTo(-Math.PI);
        removeChart(chart);
    });

    it('explicit clockwise: false matches the default', function () {
        const { chart, radar } = getRadar(false);
        const angles = radar.getIndicatorAxes().map(axis => axis.angle);
        expect(angles[0]).toBeCloseTo(Math.PI / 2);
        expect(angles[1]).toBeCloseTo(0);
        removeChart(chart);
    });

    it('clockwise: true flips the indicator ordering direction', function () {
        const { chart, radar } = getRadar(true);
        const angles = radar.getIndicatorAxes().map(axis => axis.angle);
        expect(angles[0]).toBeCloseTo(Math.PI / 2);
        expect(angles[1]).toBeCloseTo(Math.PI);
        expect(angles[2]).toBeCloseTo(-Math.PI / 2);
        expect(angles[3]).toBeCloseTo(0);
        removeChart(chart);
    });

    it('dataToPoint mirrors points across the start axis when flipped', function () {
        const { chart, radar } = getRadar(false);
        const { chart: chart2, radar: radar2 } = getRadar(true);
        const axes = radar.getIndicatorAxes();
        const axes2 = radar2.getIndicatorAxes();
        for (let i = 0; i < axes.length; i++) {
            const pt = radar.dataToPoint(5, i);
            const pt2 = radar2.dataToPoint(5, i);
            // Same distance from the center.
            const dist = Math.hypot(pt[0] - radar.cx, pt[1] - radar.cy);
            const dist2 = Math.hypot(pt2[0] - radar2.cx, pt2[1] - radar2.cy);
            expect(dist2).toBeCloseTo(dist);
            // Mirrored vertically (y axis through center, startAngle = 90).
            expect(pt2[0]).toBeCloseTo(2 * radar.cx - pt[0]);
            expect(pt2[1]).toBeCloseTo(pt[1]);
        }
        removeChart(chart);
        removeChart(chart2);
    });
});

